def matmul_tiled[
    size: Int,
    Engine: TensorEngine,
](
    output: TileTensor[
        mut=True, dtype, LayoutTiledType, MutAnyOrigin, Engine=Engine
    ],
    a: TileTensor[
        mut=False, dtype, LayoutTiledType, ImmutAnyOrigin, Engine=Engine
    ],
    b: TileTensor[
        mut=False, dtype, LayoutTiledType, ImmutAnyOrigin, Engine=Engine
    ],
) where (Engine.element_size == 1):
    var local_row = thread_idx.y
    var local_col = thread_idx.x
    var tiled_row = block_idx.y * TPB + local_row
    var tiled_col = block_idx.x * TPB + local_col

    var a_shared = stack_allocation[dtype=dtype, address_space=.SHARED](
        row_major[TPB, TPB]()
    )
    var b_shared = stack_allocation[dtype=dtype, address_space=.SHARED](
        row_major[TPB, TPB]()
    )

    var acc: output.ElementType = 0

    # Iterate over tiles to compute matrix product
    comptime for tile in range(ceildiv(size, TPB)):
        # Load A tile - global row stays the same, col determined by tile
        if tiled_row < size and (tile * TPB + local_col) < size:
            a_shared[local_row, local_col] = rebind[Scalar[dtype]](
                a[tiled_row, tile * TPB + local_col]
            )

        # Load B tile - row determined by tile, global col stays the same
        if (tile * TPB + local_row) < size and tiled_col < size:
            b_shared[local_row, local_col] = rebind[Scalar[dtype]](
                b[tile * TPB + local_row, tiled_col]
            )

        barrier()

        # Matrix multiplication within the tile
        if tiled_row < size and tiled_col < size:
            comptime for k in range(min(Int(TPB), Int(size - tile * TPB))):
                acc += a_shared[local_row, k] * b_shared[k, local_col]

        barrier()

    # Write out final result
    if tiled_row < size and tiled_col < size:
        output[tiled_row, tiled_col] = acc
